edits.oldText:
if self.underline:
    append("text-decoration: underline")
if self.strike:
    append("text-decoration: line-through")

edits.newText:
if self.underline:
    if self.double_underline:
        append("text-decoration: underline double")
    else:
        append("text-decoration: underline")
elif self.double_underline:
    append("text-decoration: underline double")
if self.strike:
    append("text-decoration: line-through")

edits.oldText:
new_style._attributes = (self._attributes & ~style._set_attributes) | (
    style._attributes & style._set_attributes
)

edits.newText:
new_style._attributes = (self._attributes & ~style._set_attributes) | (
    style._attributes & style._set_attributes
)
if (self.double_underline is False and style.double_underline is True) or (
    self.double_underline is True and style.double_underline is False
):
    new_style._attributes &= ~self.underline.bit

if style.underline:
    if style.double_underline:
        css_rules.append("text-decoration: underline double;")
    else:
        css_rules.append("text-decoration: underline;")
elif style.double_underline:
    css_rules.append("text-decoration: underline double;")
